			try {
				submitScanForm(scan.form, scan.input);
				result = await wait.promise;
			} finally {
				unpinExamOptions();
			}
			const debug = {
				request: {
					path: "page scan form",
					payload: {
						code,
						lesson_id: centerLessonId
					}
				},
				observer: result === "timeout" ? "timeout" : result.type
			};
			if (result === "timeout") {
				recordRow({
					code,
					label: entry.label,
					status: "timeout",
					message: t("data.center.noConfirmation"),
					at: Date.now(),
					debug: {
						...debug,
						note: `No matching attendance event within ${timeoutMs}ms from ${scan.inputSelector}`
					}
				});
				consecutiveTimeouts++;
				if (consecutiveTimeouts >= 3) {
					stopped = true;
					break;
				}
				continue;
			}
			consecutiveTimeouts = 0;
			if (result.type === "add") {
				if (!examTarget) undoRedo.ensureAttendanceRecorded(result.record);
				recordRow({
					code,
					label: entry.label,
					status: "created",
					message: t("data.run.registered"),
					recordId: result.record.id,
					at: Date.now(),
					debug
				});
			} else if (result.type === "duplicate") recordRow({
				code,
				label: entry.label,
				status: "duplicate",
				message: t("data.run.alreadyRegistered"),
				recordId: result.record.id,
				at: Date.now(),
				debug
			});
			else recordRow({
				code,
				label: entry.label,
				status: "error",
				message: t("data.center.unexpectedResponse"),
				at: Date.now(),
				debug
			});
