			if (bulkModeLabel) bulkModeLabel.textContent = examAttendance ? t("ui.bulk.exam.modeLabel") : t("ui.bulk.attendance.modeLabel");
			const evalTitle = evalRoot.querySelector("[data-eval-head-title]");
			const evalSubtitle = evalRoot.querySelector("[data-eval-head-subtitle]");
